// Central tool registry for all 50 FurTools tools.
// Each entry drives routing, SEO, sitemap, related-tools, search, and page rendering.

export type ToolLayout = "calculator" | "generator" | "guide";

export interface ToolExample {
  label: string;
  result: string;
}

export interface RelatedArticle {
  title: string;
  slug: string; // /blog/{slug}
}

export interface ToolFaq {
  q: string;
  a: string;
}

export interface Tool {
  slug: string;
  name: string;
  tagline: string;
  description: string;
  category: "dogs" | "cats" | "birds" | "fish" | "small-pets" | "reptiles" | "horses" | "farm" | "general";
  keywords: string[];
  layout: ToolLayout;
  featured?: boolean;
  popular?: boolean;
  medicalDisclaimer?: boolean;
  howItWorks: string;
  examples: ToolExample[];
  faqs: ToolFaq[];
  relatedArticles: RelatedArticle[];
  updatedAt: string;
}

