    howItWorks:
      "Each trick uses either luring (guide with treat), capturing (mark a naturally occurring behavior), or shaping (reward closer and closer approximations). Beginners should master 3-5 beginner tricks before attempting intermediate. Sessions should stay short — 5 successful reps and stop. When 'proofing' a new trick, generalize it to three locations before considering it learned. Every trick reinforces the marker (click or 'Yes!') and pays with high-value food.",
