      "Cats and rabbits are two of the easiest species to litter train — they instinctively prefer a consistent bathroom spot — but the setup is completely different for each. Cats need unscented clumping litter in a low-traffic box with the '1 per cat + 1' rule. Rabbits need paper-based litter, hay on top, and never clumping clay (which is toxic if ingested). This planner walks through the 3-week timeline for each species, from first setup to reliable free-roam privileges. Regression after training is usually medical (UTI, stones) — not behavioral.",
    category: "general",
    keywords: ["litter training cat", "litter training rabbit", "kitten litter box", "rabbit litter box", "house training"],
    layout: "guide", popular: true,
    howItWorks:
      "For cats: unscented clumping litter (Dr. Elsey's, Tidy Cats), 3-inch depth, box in a quiet spot away from food. Place kitten in box after meals and naps. Scoop twice daily. Never punish accidents. For rabbits: paper-based litter (Yesterday's News, Carefresh), hay on top, corner box inside enclosure. Rabbits chew and eliminate simultaneously — hay makes the box magnetic. Spay/neuter around 4-6 months dramatically improves rabbit litter reliability.",
    examples: [
      { label: "Cat: Day 1-7", result: "Box in quiet spot, praise after meals" },
      { label: "Rabbit: Day 1-7", result: "Paper litter + hay on top" },
      { label: "Week 3", result: "Free-roam privileges once 80% reliable" },
    ],
    faqs: [
      { q: "Why does my cat pee outside the box?", a: "First rule out medical (UTI, crystals, kidney disease, arthritis) with a vet. Then check: dirty box, wrong litter type, wrong box location, not enough boxes, or a bully cat blocking access. Rarely truly behavioral." },
      { q: "How many litter boxes do I need for cats?", a: "One per cat plus one extra. Two cats = 3 boxes, in different locations. Cats often refuse to share, and territorial issues cause many 'inappropriate elimination' cases." },
      { q: "What litter is best for kittens?", a: "Unscented, non-clumping (until 3-4 months when they stop tasting everything), low-dust. Once older, switch to unscented clumping. Avoid crystal, pine pellets, or corn-based litters until they're proven not to eat them." },
      { q: "Can rabbits use clay cat litter?", a: "Absolutely not. Clay litter is deadly to rabbits if ingested (which they will, they eat everything in the box). Use paper-based, aspen shavings, or compressed grass pellets only." },
      { q: "How long does rabbit litter training take?", a: "1-4 weeks for most rabbits. Spayed/neutered adults train fastest (95%+ reliable). Intact rabbits often mark territory and are much harder to train — hormones override instinct." },
      { q: "What if I have both cats and rabbits?", a: "Keep their litter setups completely separate. Rabbits will eat cat litter (dangerous); cats will use rabbit boxes as chew stations. Different locations, different rooms if possible." },
      { q: "My cat only pees in one specific spot — what do I do?", a: "Move a litter box to that exact spot temporarily. Once they use it there for a week, move it 6 inches per day toward the desired location. Also enzymatic-clean the old spot thoroughly." },
      { q: "How often should I clean the litter box?", a: "Cats: scoop twice daily, dump-and-clean weekly. Rabbits: change entire box every 3-4 days (they poop more). Both species will boycott a dirty box quickly." },
      { q: "Is covered vs uncovered box better?", a: "Cats: most prefer uncovered (better ventilation, no ambush anxiety). Rabbits: uncovered corner box works best. Try both if you're unsure — cats vote with their feet." },
      { q: "What if my adult cat suddenly stops using the box?", a: "Vet appointment within 3 days. Sudden litter avoidance in an adult cat is almost always medical — UTI, bladder stones, arthritis, or cognitive dysfunction in seniors. Never assume it's behavioral first." },
      ...COMMON_FAQS,
    ],
    relatedArticles: CAT_ARTICLES, updatedAt: "2026-07-16",
