    howItWorks: "Ground surfaces absorb solar radiation and can be dramatically hotter than the air. Studies using infrared thermometers show asphalt in direct sun runs 40-60°F above ambient, concrete 20-30°F, sand 30-45°F, grass barely 5°F above. Dog paw pads sustain thermal burns at approximately 125°F (52°C) with prolonged contact, and blister within seconds above 140°F. The tool applies research-backed surface offsets to your air temperature and sun conditions to output an estimated pad temperature and a safe-contact window.",
