    howItWorks: "Emergency vet visits spike during the holidays, with pancreatitis, foreign body obstruction and toxic ingestion topping the list. This lookup indexes the most common decorations, plants, foods and beverages found in December homes. Each entry is tagged 'toxic', 'hazard' or 'caution' and includes practical guidance drawn from ASPCA and Pet Poison Helpline case data.",
