export function getTool(slug: string): Tool | undefined {
  return TOOLS.find((t) => t.slug === slug);
}

export function toolsByCategory(categorySlug: string): Tool[] {
  return TOOLS.filter((t) => t.category === categorySlug);
}

export function featuredTools(limit = 4): Tool[] {
  return TOOLS.filter((t) => t.featured).slice(0, limit);
}

export function popularTools(limit = 6): Tool[] {
  return TOOLS.filter((t) => t.popular).slice(0, limit);
}

export function relatedTools(slug: string, limit = 3): Tool[] {
  const tool = getTool(slug);
  if (!tool) return [];
  const others = TOOLS.filter((t) => t.slug !== slug);
  const scored = others.map((t) => {
    let score = 0;
    if (t.category === tool.category) score += 5;
    const overlap = t.keywords.filter((k) => tool.keywords.includes(k)).length;
    score += overlap;
    return { t, score };
  });
  return scored
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((s) => s.t);
}

export function searchTools(query: string): Tool[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  return TOOLS.filter((t) => {
    return (
      t.name.toLowerCase().includes(q) ||
      t.tagline.toLowerCase().includes(q) ||
      t.description.toLowerCase().includes(q) ||
      t.keywords.some((k) => k.toLowerCase().includes(q))
    );
  });
}
